ALTER TABLE payment_records ADD COLUMN IF NOT EXISTS razorpay_order_id VARCHAR(100) UNIQUE;
ALTER TABLE payment_records ADD COLUMN IF NOT EXISTS razorpay_payment_id VARCHAR(100) UNIQUE;
CREATE TABLE IF NOT EXISTS payment_refunds(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payment_records(id),razorpay_refund_id VARCHAR(100) UNIQUE,amount_paise BIGINT NOT NULL CHECK(amount_paise>0),status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settlement_entries(id UUID PRIMARY KEY,payment_id UUID NOT NULL REFERENCES payment_records(id),vendor_id UUID NOT NULL REFERENCES vendors(id),gross_paise BIGINT NOT NULL,fee_paise BIGINT NOT NULL DEFAULT 0,net_paise BIGINT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notification_outbox(id UUID PRIMARY KEY,recipient VARCHAR(254) NOT NULL,channel VARCHAR(20) NOT NULL CHECK(channel IN ('EMAIL','SMS')),subject VARCHAR(200),body VARCHAR(4000) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ);
